pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address ownerCaller, address _owner) public {
        vm.assume(ownerCaller != address(0));
        vm.assume(_owner != address(0));
        vm.prank(address(this));
        c.setOwner(ownerCaller);
        vm.prank(ownerCaller);
        c.setOwner(_owner);
        assertEq(c.owner(), _owner);
    }
}
